ApiConfigText.value:
"{
  "format": "warudodc.api-config.experimental",
  "version": 2,
  "events": [
    {
      "route": "adapter_to_link",
      "key": "autonomy.mode.free",
      "enabled": true,
      "description": "请求进入自由模式，不自动移动角色；现有返回待命过渡期间拒绝。业务结果经autonomy.state.result返回。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "autonomy.mode.standby",
      "enabled": true,
      "description": "请求沿既有返回待命流程回到待命；实际完成后经autonomy.state.result回执。重复在途请求拒绝，ACK不表示模式已改变。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "autonomy.move_by",
      "enabled": true,
      "description": "按世界坐标相对当前位置移动 delta，沿用自主行动守卫与软边界。",
      "ack_timeout_ms": 30000,
      "fields": [
        {
          "key": "delta",
          "kind": "vector3",
          "description": "世界坐标位移（米），不是角色局部前后左右。"
        }
      ]
    },
    {
      "route": "adapter_to_link",
      "key": "autonomy.move_to",
      "enabled": true,
      "description": "请求角色自主移动到目标世界坐标；最终是否执行由主场景 Autonomy Controller 决定。",
      "ack_timeout_ms": 30000,
      "fields": [
        {
          "key": "target",
          "kind": "vector3",
          "description": "期望到达的世界坐标；主场景会将其限制在桌面软边界内。"
        }
      ]
    },
    {
      "route": "adapter_to_link",
      "key": "autonomy.rotate_by",
      "enabled": true,
      "description": "水平自主转向，遵守本地交互策略，实际执行由 Locomotion Turn 负责。",
      "ack_timeout_ms": 30000,
      "fields": [
        {
          "key": "delta_yaw",
          "kind": "float",
          "description": "相对当前水平朝向的增量（度），限制 [-180,180]，走最短路径。"
        }
      ]
    },
    {
      "route": "adapter_to_link",
      "key": "autonomy.rotate_to",
      "enabled": true,
      "description": "水平自主转向，遵守本地交互策略，实际执行由 Locomotion Turn 负责。",
      "ack_timeout_ms": 30000,
      "fields": [
        {
          "key": "yaw",
          "kind": "float",
          "description": "世界水平朝向（度），限制 [0,360]。"
        }
      ]
    },
    {
      "route": "adapter_to_link",
      "key": "expression.aggrieved",
      "enabled": true,
      "description": "请求显示委屈：被误解、受到冷落或希望得到安慰；区别于一般悲伤、责怪和愤怒。 仅提交REQUESTED，由场景控制合成按本地持续/限时设置恢复。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "expression.bored",
      "enabled": true,
      "description": "请求显示无聊：兴致缺缺、敷衍或等待太久；不同于身体疲倦、愤怒或受到冒犯。 仅提交REQUESTED，由场景控制合成按本地持续/限时设置恢复。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "expression.confused",
      "enabled": true,
      "description": "请求显示疑惑表情；按当前情绪选择本地图内差分，自动恢复到届时有效表情，不抢占交互表情。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "expression.disgusted",
      "enabled": true,
      "description": "请求显示嫌弃：对具体对象或行为表示排斥、嫌弃或不想靠近；不用于单纯没听懂。 仅提交REQUESTED，由场景控制合成按本地持续/限时设置恢复。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "expression.displeased",
      "enabled": true,
      "description": "请求显示不满：抗议、责怪或表达个人边界的即时反应；不是改变角色长期基础情绪。 仅提交REQUESTED，由场景控制合成按本地持续/限时设置恢复。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "expression.embarrassed",
      "enabled": true,
      "description": "请求显示尴尬：出糗、被拆穿或社交窘迫；正向亲昵和夸奖后的羞涩使用expression.shy。仅提交REQUESTED，按当前场景规则合成并自动恢复。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "expression.expectant",
      "enabled": true,
      "description": "请求显示期待：期待答案、礼物或接下来的互动，积极地等待；不是已经得到结果后的得意。 仅提交REQUESTED，由场景控制合成按本地持续/限时设置恢复。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "expression.fearful",
      "enabled": true,
      "description": "请求显示害怕：受到威胁、恐惧或受惊；普通意外消息使用惊讶，不要把惊喜解释为恐惧。 仅提交REQUESTED，由场景控制合成按本地持续/限时设置恢复。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "expression.playful",
      "enabled": true,
      "description": "请求显示俏皮：调侃、逗弄或善意使坏时的俏皮反应；不要用于严肃关切或对方明显不适时。 仅提交REQUESTED，由场景控制合成按本地持续/限时设置恢复。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "expression.relieved",
      "enabled": true,
      "description": "请求显示释然：放下顾虑、确认安全或松了一口气；关注担忧解除的转折，而非所有普通开心。 仅提交REQUESTED，由场景控制合成按本地持续/限时设置恢复。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "expression.shy",
      "enabled": true,
      "description": "请求显示害羞：被亲近或夸奖后的正向羞涩、欲言又止；出糗和社交窘迫使用尴尬。 仅提交REQUESTED，由场景控制合成按本地持续/限时设置恢复。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "expression.skeptical",
      "enabled": true,
      "description": "请求显示怀疑：已经听懂但不太相信、质疑真实性或动机；不理解含义时使用困惑。 仅提交REQUESTED，由场景控制合成按本地持续/限时设置恢复。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "expression.smug",
      "enabled": true,
      "description": "请求显示得意：被夸奖、完成事情或小小炫耀后的自得；不是所有开心片段都需要得意。 仅提交REQUESTED，由场景控制合成按本地持续/限时设置恢复。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "expression.speechless",
      "enabled": true,
      "description": "请求显示无语表情；按当前情绪选择本地图内差分，自动恢复到届时有效表情，不抢占交互表情。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "expression.surprised",
      "enabled": true,
      "description": "请求显示惊讶表情；按当前情绪选择本地图内差分，自动恢复到届时有效表情，不抢占交互表情。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "expression.tender",
      "enabled": true,
      "description": "请求显示温柔：安慰、关爱或温柔亲昵地回应；无需每次礼貌回答都添加此表情。 仅提交REQUESTED，由场景控制合成按本地持续/限时设置恢复。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "expression.thinking",
      "enabled": true,
      "description": "请求思考表情；场景DurationSeconds=0持续到替换/释放，正数限时；不代表模型内部推理。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "expression.tired",
      "enabled": true,
      "description": "请求显示疲惫：对话中展示疲劳、困倦或勉强打起精神；仅是表现请求，不证明本地生理状态已产生。 仅提交REQUESTED，由场景控制合成按本地持续/限时设置恢复。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "expression.worried",
      "enabled": true,
      "description": "请求显示担忧：担心对方、犹豫或预感不妙；是关切，不等于自己已经受到直接威胁。 仅提交REQUESTED，由场景控制合成按本地持续/限时设置恢复。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "idle.return_normal_pose",
      "enabled": true,
      "description": "让 Idle Controller 按当前 Emotion 重新选择基础待机动画；仅在基础动画所有权为空时生效，适合作为 Director cleanup_cues。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "performance.thinking.end",
      "enabled": true,
      "description": "结束当前来源为思考的表情和思考姿态，保留其他来源；经autonomy.state.result报告实际状态。可作为Director cleanup。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "performance.thinking.start",
      "enabled": true,
      "description": "请求进入思考状态：在本地许可后提交思考表情和姿态；ThinkingDurationSeconds=0持续到结束/替代，正数限时。立即经autonomy.state.result报告本地受理结果，不等待思考结束。",
      "ack_timeout_ms": 30000,
      "fields": []
    },
    {
      "route": "adapter_to_link",
      "key": "performance.wave_once",
      "enabled": true,
      "description": "单次限时挥手；本地空闲且无交互时播放，约 2.5 秒后释放动画所有权并回归当前基础姿态。message 为可选说明，不作为动作完成回执。",
      "ack_timeout_ms": 30000,
      "fields": [
        {
          "key": "message",
          "kind": "string",
          "description": "Director 为该表现提示附带的可读说明；示例链不据此分支。"
        }
      ]
    },
    {
      "route": "link_to_adapter",
      "key": "autonomy.move_by.result",
      "enabled": true,
      "description": "实际到达后返回；reply_to 关联 autonomy.move_by，拒绝或中止不伪报成功。",
      "ack_timeout_ms": 30000,
      "fields": [
        {
          "key": "position",
          "kind": "vector3",
          "description": "实际完成世界坐标。"
        },
        {
          "key": "status",
          "kind": "string",
          "description": "完成为 completed。"
        }
      ]
    },
    {
      "route": "link_to_adapter",
      "key": "autonomy.move_to.result",
      "enabled": true,
      "description": "角色确实到达本次自主移动目标后返回；reply_to 关联原 autonomy.move_to 事件。",
      "ack_timeout_ms": 30000,
      "fields": [
        {
          "key": "position",
          "kind": "vector3",
          "description": "完成时角色节点的世界坐标。"
        },
        {
          "key": "status",
          "kind": "string",
          "description": "业务终态；首版成功路径固定为 completed。"
        }
      ]
    },
    {
      "route": "link_to_adapter",
      "key": "autonomy.rotate_by.result",
      "enabled": true,
      "description": "转向实际完成后返回；reply_to 关联 autonomy.rotate_by。",
      "ack_timeout_ms": 30000,
      "fields": [
        {
          "key": "rotation",
          "kind": "vector3",
          "description": "实际完成的世界欧拉角（度）。"
        },
        {
          "key": "status",
          "kind": "string",
          "description": "完成为 completed。"
        }
      ]
    },
    {
      "route": "link_to_adapter",
      "key": "autonomy.rotate_to.result",
      "enabled": true,
      "description": "转向实际完成后返回；reply_to 关联 autonomy.rotate_to。",
      "ack_timeout_ms": 30000,
      "fields": [
        {
          "key": "rotation",
          "kind": "vector3",
          "description": "实际完成的世界欧拉角（度）。"
        },
        {
          "key": "status",
          "kind": "string",
          "description": "完成为 completed。"
        }
      ]
    },
    {
      "route": "link_to_adapter",
      "key": "autonomy.state.result",
      "enabled": true,
      "description": "行动状态工具的关联业务结果：status为Succeeded或Rejected，mode为实际模式0待命/1自由，thinking表示仍持有思考表情或姿态；关联事件ID指向原工具事件。",
      "ack_timeout_ms": 30000,
      "fields": [
        {
          "key": "detail",
          "kind": "string",
          "description": "操作结果或拒绝原因"
        },
        {
          "key": "mode",
          "kind": "integer",
          "description": "实际行动模式：0待命，1自由"
        },
        {
          "key": "status",
          "kind": "string",
          "description": "Succeeded或Rejected，不是传输ACK"
        },
        {
          "key": "thinking",
          "kind": "boolean",
          "description": "是否仍持有思考表情或姿态"
        }
      ]
    },
    {
      "route": "link_to_adapter",
      "key": "interaction.back_drag.phase_2",
      "enabled": true,
      "description": "Back Drag 进入 Phase 2；默认阈值约 3000 ms。",
      "ack_timeout_ms": 30000,
      "fields": [
        {
          "key": "activity_mode",
          "kind": "string",
          "description": "standby/free/unknown"
        },
        {
          "key": "duration_ms",
          "kind": "integer",
          "description": "该阶段的实际持续时间阈值（毫秒）。"
        },
        {
          "key": "energy",
          "kind": "float",
          "description": "0~100"
        },
        {
          "key": "energy_state",
          "kind": "string",
          "description": "unavailable/normal/low"
        },
        {
          "key": "feeling_adaptation",
          "kind": "float",
          "description": "发送时对同类刺激的适应程度，0..1；不是好感度。"
        },
        {
          "key": "feeling_available",
          "kind": "boolean",
          "description": "本次事件发送时该部位的感受数据是否可用；false时忽略三个感受数值。"
        },
        {
          "key": "feeling_comfort",
          "kind": "float",
          "description": "发送时的暂定本地舒适倾向，-1..1；不等于角色Emotion。"
        },
        {
          "key": "feeling_load",
          "kind": "float",
          "description": "发送时该部位的累积刺激负荷，0..1；不是情绪或强制表现指令。"
        },
        {
          "key": "interaction_serial",
          "kind": "integer",
          "description": "本次交互代次；用于诊断和去重。"
        }
      ]
    },
    {
      "route": "link_to_adapter",
      "key": "interaction.back_drag.phase_3",
      "enabled": true,
      "description": "Back Drag 进入 Phase 3；默认阈值约 15000 ms。",
      "ack_timeout_ms": 30000,
      "fields": [
        {
          "key": "activity_mode",
          "kind": "string",
          "description": "standby/free/unknown"
        },
        {
          "key": "duration_ms",
          "kind": "integer",
          "description": "该阶段的实际持续时间阈值（毫秒）。"
        },
        {
