          "kind": "float",
          "description": "发送时该部位的累积刺激负荷，0..1；不是情绪或强制表现指令。"
        },
        {
          "key": "interaction_serial",
          "kind": "integer",
          "description": "本次交互代次；用于诊断和去重。"
        }
      ]
    },
    {
      "route": "link_to_adapter",
      "key": "interaction.back_drag.phase_4",
      "enabled": true,
      "description": "Back Drag 进入 Phase 4；默认阈值约 30000 ms。",
      "ack_timeout_ms": 30000,
      "fields": [
        {
          "key": "activity_mode",
          "kind": "string",
          "description": "standby/free/unknown"
        },
        {
          "key": "duration_ms",
