        }
      ]
    },
    {
      "route": "link_to_adapter",
      "key": "interaction.contact_belly.stroke",
      "enabled": true,
      "description": "角色腹部接触持续进入 Phase 3，结算为一次抚摸。",
      "ack_timeout_ms": 30000,
      "fields": [
        {
          "key": "activity_mode",
          "kind": "string",
          "description": "standby/free/unknown"
        },
        {
          "key": "energy",
          "kind": "float",
          "description": "0~100"
        },
        {
          "key": "energy_state",
          "kind": "string",
          "description": "unavailable/normal/low"
        },
        {
